 }
 async function gitFmDo(action) {
   const out = document.getElementById('gitfm-out');
   if (out) { out.textContent = '…'; out.style.color = 'var(--t2)'; }
   try {
     const r = await fetch('/api/git/fm', {
       method: 'POST',
       headers: { 'Content-Type': 'application/json' },
       body: JSON.stringify({
         path: fmCurrentPath,
         action,
         message: (document.getElementById('gitfm-msg') || {}).value || '',
         branch: (document.getElementById('gitfm-branch') || {}).value || '',
         remote: (document.getElementById('gitfm-remote') || {}).value || ''
       })
     }).then(r => r.json());
     let text;
     if (r.needRemote) {
       text = '✗ ' + (r.error || 'Заполни URL репозитория выше и повтори');
       const rem = document.getElementById('gitfm-remote');
       if (rem) rem.focus();
     } else if (r.needInit) {
       text = '✗ ' + (r.error || 'Сначала создай репо') + ' — жми «Создать репо» или укажи remote и «Коммит + push»';
     } else if (r.success) {
       text = '✓ ' + (r.out || 'готово');
       fmRefresh();
       gitFmShow();
     } else {
       text = '✗ ' + (r.error || 'ошибка');
     }
     if (out) { out.textContent = text; out.style.color = r.success ? 'var(--ok)' : 'var(--err)'; }
   } catch (e) {
     if (out) { out.textContent = '✗ ' + e.message; out.style.color = 'var(--err)'; }
   }
 }

 function setupDropZone() {
   const zone = document.getElementById('fm-list');
   if (!zone || zone.dataset.dz) return;
   zone.dataset.dz = '1';
   const paint = on => {
     zone.style.borderColor = on ? 'var(--acc)' : '';
     zone.style.background = on ? 'rgba(88,166,255,.08)' : '';
   };
   zone.addEventListener('dragover', e => { e.preventDefault(); paint(true); });
   zone.addEventListener('dragleave', () => paint(false));
   zone.addEventListener('drop', e => {
     e.preventDefault(); paint(false);
     const files = [];
     const reads = [];
     const walk = (entry, out, base) => {
       if (!entry) return;
       if (entry.isFile) {
         reads.push(new Promise(res => entry.file(f => { files.push({ f, base }); res(); })));
       } else if (entry.isDirectory) {
         const reader = entry.createReader();
         reads.push(new Promise(res => {
           const todo = [];
           const more = () => reader.readEntries(chunk => {
             if (!chunk || !chunk.length) { res(); return; }
             chunk.forEach(c => walk(c, out, (base ? base + c.name + '/' : c.name + '/')));
             more();
           }, () => res());
           more();
         }));
       }
     };
     const items = [...(e.dataTransfer && e.dataTransfer.items || [])];
     if (!items.length) {
       // Старые браузеры / plain files без entries.
       [...(e.dataTransfer && e.dataTransfer.files || [])].forEach(f => files.push({ f, base: '' }));
     } else {
       items.forEach(item => {
         if (item.kind === 'file') walk(item.webkitGetAsEntry && item.webkitGetAsEntry(), null, '');
       });
     }
     Promise.all(reads).then(() => {
       const fl = files.map(o => o.f);
       uploadFiles(fl, files.map(o => (o.base || '') + o.f.name));
     });
   });
 }
 document.addEventListener('DOMContentLoaded', () => setTimeout(setupDropZone, 300));

