     const line = term.buffer.active.getLine(cell.row);
     if (!line) return false;
     const text = line.translateToString(true);
     const isWord = (ch) => !!ch && !/\s/.test(ch);
     let s = Math.min(cell.col, Math.max(0, text.length - 1));
     let e = s;
