 // ===== AUDIO KEEP-ALIVE (background playback) =====
 let _audioCtx = null;
 let _silentOsc = null;
 let _keepAliveInterval = null;

 function _ensureAudioCtx() {
   if (_audioCtx) return _audioCtx;
   try {
     const AC = window.AudioContext || window.webkitAudioContext;
     if (!AC) return null;
     _audioCtx = new AC();
     // Silent oscillator — keeps AudioContext alive in background
     _silentOsc = _audioCtx.createOscillator();
     const gain = _audioCtx.createGain();
     gain.gain.value = 0;
     _silentOsc.connect(gain);
     gain.connect(_audioCtx.destination);
     _silentOsc.start();
     return _audioCtx;
   } catch { return null; }
 }

 function _resumeAudio() {
   try {
     if (_audioCtx && _audioCtx.state === 'suspended') _audioCtx.resume();
   } catch {}
 }

 // Resume audio on any user interaction (required by browsers)
 ['click','touchstart','keydown','mousedown'].forEach(evt => {
   document.addEventListener(evt, () => {
     _ensureAudioCtx();
     _resumeAudio();
     // A user gesture unlocks the phone speaker; the PCM stream then carries
     // audio from the video playing in remote Chromium.
     try { if (typeof remoteAudioStart === 'function') remoteAudioStart(); } catch {}
     // Also resume all iframes (YouTube, noVNC)
     document.querySelectorAll('iframe').forEach(f => {
       try { f.contentWindow.postMessage({type:'audio-resume'}, '*'); } catch {}
     });
   }, { passive: true });
 });

 // Handle visibility change — re-init audio when returning to tab
 document.addEventListener('visibilitychange', () => {
   if (document.hidden) return;
   _resumeAudio();
   if (typeof tabs === 'undefined') return;
   // Kick any broken terminal back to life the moment the page is visible
   // again (background sleep drops the WS; a plain onclose delay is too slow).
   tabs.forEach(t => {
     if (t.manualClose || !t.connect) return;
     const s = t.socket;
     if (s && s.readyState === WebSocket.OPEN) {
       // Looks open but silent for too long → dead on the far side (tunnel
       // flap during background). Force it closed so onclose reconnects at once.
       if (t.lastPong && Date.now() - t.lastPong > 45000) { t.retry = 0; try { s.close(); } catch {} }
       return;
     }
     if (s && s.readyState === WebSocket.CONNECTING) return; // connect watchdog aborts stale attempts
     if (t.reconnectTimer) { clearTimeout(t.reconnectTimer); t.reconnectTimer = null; }
     hideCountdown(t.id);
     t.lastPong = 0; t.retry = 0;
     try { t.connect(); } catch (e) { /* ignore */ }
   });
 });
 // Also recover the moment connectivity returns.
 window.addEventListener('online', () => {
   if (typeof tabs === 'undefined') return;
   tabs.forEach(t => {
     if (t.manualClose || !t.connect) return;
     const s = t.socket;
     if (s && s.readyState === WebSocket.OPEN) return;
     if (s && s.readyState === WebSocket.CONNECTING) return;
     if (t.reconnectTimer) { clearTimeout(t.reconnectTimer); t.reconnectTimer = null; }
     hideCountdown(t.id);
     t.lastPong = 0; t.retry = 0;
     try { t.connect(); } catch (e) { /* ignore */ }
   });
 });

 // Periodic keep-alive — ping server every 30s to keep tunnel/session alive
 _keepAliveInterval = setInterval(() => {
   // In the background the audio WebSocket already keeps the tunnel warm; an
   // extra HTTP poll only wakes the radio (battery). Ping only while visible.
   if (document.hidden) return;
   fetch('/api/pulse/status').catch(() => {});
 }, 30000);

 // Prevent page sleep (keeps audio + WebSocket alive on mobile)
 (function _preventSleep() {
   // Init silent audio keep-alive
   try {
     const el = document.getElementById('keepalive-audio');
     if (el) {
       const ctx = new (window.AudioContext || window.webkitAudioContext)();
       const buf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
       const src = ctx.createBufferSource();
       src.buffer = buf;
       src.loop = true;
       src.connect(ctx.destination);
       src.start();
       el._ctx = ctx;
       el._src = src;
     }
   } catch {}

   let wakeLock = null;
   async function requestWake() {
     if ('wakeLock' in navigator && !document.hidden) {
       try { wakeLock = await navigator.wakeLock.request('screen'); } catch {}
     }
   }
   document.addEventListener('visibilitychange', () => {
     if (!document.hidden) requestWake();
     else if (wakeLock) { wakeLock.release(); wakeLock = null; }
   });
   requestWake();
 })();

 // ===== SNAPSHOT TAB — выборочное восстановление локальных репозиториев =====
 // Вход в хаб не ждёт скачивание бэкапов; снапшот выбирается здесь, после входа.
 // Сервер читает только «дерево» ветки work-backup (список+размеры), поэтому
 // список открывается быстро даже если в ветке сотни мегабайт.
 let snapData = { snapshots: [], recommended: '' }, snapSelected = '', snapPoll = null;
 function snapEsc(s) { return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }
 function snapMb(n) { const v = Math.round((n || 0) / 104857.6) / 10; return v >= 1 ? (v + ' МБ') : ((Math.round((n || 0) / 1048.576)) + ' КБ'); }
 async function initSnapshots() {
   // Висящий рестарт хаба не теряет уже работающее восстановление — подхватываем.
   try {
     const j = await fetch('/api/work-snapshots/restore/status').then(r => r.json());
     if (j && j.running) { showSnapProgress(); pollSnap(); return; }
   } catch (e) {}
   if (!snapData.snapshots.length) snapLoad();
 }
 async function snapLoad(force) {
   const note = document.getElementById('snap-note'), list = document.getElementById('snap-list');
   if (force) note.textContent = 'Читаю ветку work-backup…';
   try {
     const j = await fetch('/api/work-snapshots').then(r => r.json());
     if (!j || j.success !== true) { note.textContent = 'Не прочиталось: ' + (j && j.error || '?'); return; }
     snapData = { snapshots: j.snapshots || [], recommended: j.recommended || '' };
     snapSelected = snapSelected || snapData.recommended || (snapData.snapshots[0] || {}).stamp || '';
     renderSnapList();
     if (snapData.snapshots.length) {
       note.textContent = j.note || ('Снапшотов: ' + snapData.snapshots.length + '. По умолчанию — последний с целыми репозиториями.');
     } else {
       note.textContent = j.note || 'Снапшотов пока нет — раннер ещё не сохранял репозитории.';
       list.innerHTML = '';
     }
   } catch (e) {
     note.textContent = 'Нет связи: ' + (e && e.message || e);
   }
 }
 function snapDay(s) { return s.replace(/^\d+$|\D/g, '').slice(0, 8).replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3'); }
 function renderSnapList() {
   const list = document.getElementById('snap-list');
   if (!snapData.snapshots.length) { list.innerHTML = ''; return; }
   // По дням — всегда самый новый снапшот дня; внутри дня не показываем хвосты.
   const byDay = new Map();
   for (const s of snapData.snapshots) {
     const d = snapDay(s.stamp);
     if (!byDay.has(d)) byDay.set(d, s); // список уже по убыванию: первый = новейший
   }
   const shown = [...byDay.values()];
   if (!snapData.snapshots.some(s => s.active)) snapSelected = ''; // отмечать нечего — честно
   list.innerHTML = shown.map(s => {
     const sel = s.stamp === snapSelected;
     const act = !!s.active;
     const marks = [];
     if (s.stamp === snapData.recommended) marks.push('<span style="color:var(--acc);font-weight:600">⭐ последний, где что-то делали</span>');
     if (!act) marks.push('<span style="color:var(--warn,#e0a642);font-weight:600">⚠ ничего не делали (пусто)</span>');
     const what = [];
     if (s.repos.length) what.push('репо: ' + s.repos.map(r => snapEsc(r.rel) + ' (' + r.kind + ', ' + snapMb(r.bytes) + ')').join(' | '));
     if (s.extrasMb > 0) what.push('дифы/новое: ' + s.extrasMb + ' МБ');
     if (s.chats) what.push('чаты opencode: ' + s.chats);
     if (s.settings) what.push('настройки opencode');
     if (!what.length) what.push('только файлы/аудит');
     return `<label class="snap-row ${sel ? 'sel' : ''}" data-stamp="${snapEsc(s.stamp)}" onclick="snapPick('${snapEsc(s.stamp)}')">
       <input type="radio" name="snap" ${sel ? 'checked' : ''}>
       <div style="flex:1;min-width:0">
         <div style="font-size:12px;font-weight:700;color:var(--t1)">📅 ${snapEsc(snapDay(s.stamp))} · ${snapEsc(s.stamp.slice(-6).replace(/(\d{2})(\d{2})(\d{2})/, '$1:$2:$3'))}</div>
         <div style="font-size:11px;margin-top:2px">${marks.join(' ')}</div>
         <div style="font-size:11px;color:var(--t3);margin-top:3px">${what.join(' · ')}</div>
       </div>
       <div style="font-size:11px;color:var(--t3)">${s.totalMb} МБ</div>
     </label>`;
   }).join('');
   const btn = document.getElementById('snap-restore');
   const s = snapData.snapshots.find(x => x.stamp === snapSelected);
   btn.disabled = !(s && s.active);
 }
 function snapPick(stamp) {
   snapSelected = stamp;
   renderSnapList();
 }
 async function snapRestore() {
   const s = snapData.snapshots.find(x => x.stamp === snapSelected);
   if (!s) return;
   const ok = await fmConfirm('Восстановить локальные репозитории из снапшота ' + s.stamp + '? Существующие git-репозитории не трогаются, дополняются только отсутствующие.', 'Восстановить');
   if (!ok) return;
   try {
     const r = await fetch('/api/work-snapshots/restore', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ snapshot: s.stamp }) });
     const j = await r.json();
     if (!j || j.success !== true) { fmInfo('Не запустилось: ' + (j && j.error || '?')); return; }
     showSnapProgress();
     pollSnap();
   } catch (e) {
     fmInfo('Нет связи: ' + (e && e.message || e));
   }
 }
 function showSnapProgress() {
   document.getElementById('snap-prog-wrap').style.display = '';
   document.getElementById('snap-spin').style.display = '';
   document.getElementById('snap-prog-title').textContent = 'Восстановление…';
   document.getElementById('snap-restore').disabled = true;
 }
 function pollSnap() {
   if (snapPoll) clearInterval(snapPoll);
   snapPoll = setInterval(async () => {
     let j = null;
     try { j = await fetch('/api/work-snapshots/restore/status').then(r => r.json()); } catch (e) { return; }
     if (!j) return;
     const el = document.getElementById('snap-prog');
     el.textContent = (j.tail || []).join('\n');
     el.scrollTop = el.scrollHeight;
     const sec = j.elapsed || 0;
     document.getElementById('snap-prog-time').textContent = Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0');
     if (!j.running) {
       clearInterval(snapPoll); snapPoll = null;
       document.getElementById('snap-spin').style.display = 'none';
