       <!-- FILES -->
       <div class="page on" id="p-files">
         <div class="fm-sidebar">
           <div class="fm-sidebar-title">Устройства</div>
           <div id="devices-list"></div>
           <div class="fm-sidebar-title" style="border-top:1px solid var(--bdr)">Хранилища</div>
           <div id="storages-list"></div>
           <div style="padding:8px;border-top:1px solid var(--bdr)">
             <button class="btn" onclick="showAddStorageModal()" style="width:100%;text-align:center;font-size:13px">+ Добавить</button>
           </div>
         </div>
         <div class="fm-path-row">
           <input type="text" id="fm-path" onkeydown="if(event.key==='Enter')fmBrowse(this.value)">
           <button class="btn" onclick="fmBrowse(document.getElementById('fm-path').value)">Go</button>
         </div>
         <div class="fm-header">
           <button class="btn" onclick="fmGoUp()">↑</button>
           <button class="btn" onclick="fmGoHome()">🏠</button>
           <button class="btn" onclick="fmRefresh()">⟳</button>
           <button class="btn" onclick="toggleFileSel(true)">Выделить все</button>
           <button class="btn" onclick="fmMkdir()">📁+</button>
           <button class="btn" onclick="fmCreateFile()">📄+</button>
           <button class="btn" onclick="fmRename()">✏️</button>
           <button class="btn" onclick="fmDelete()">🗑️</button>
           <button class="btn" onclick="fmDownloadMulti()" title="Скачать на телефон — файл попадёт в папку Загрузки (Download), вне Android/data">📥 Multi-download</button>
           <button class="btn" onclick="fmDownloadSingle()" title="Скачать на телефон — файл попадёт в папку Загрузки (Download), вне Android/data">⬇ Single</button>
           <button class="btn" onclick="fmOpenView()" title="Открыть во встроенном просмотрщике: текст — редактор с сохранением, фото/видео/PDF — просмотр (работает и из кеша)">👁</button>
           <button class="btn" onclick="fmCacheSelection()" title="Сохранить файл/папку в кеш на устройстве (IndexedDB) — переживает отключение раннера, как у PWA">💾 В кеш</button>
           <button class="btn" onclick="fmArchive()" title="Скачать как tar.xz (распаковывается любым архиватором)">📦</button>
           <button class="btn" onclick="fmSaveGithub()" title="Сохранить в GitHub">⬆️GH</button>
           <button class="btn" onclick="fmUpload()" title="Файлы (все виды, картинки — тоже, множественный выбор через SAF)">⬆</button>
           <button class="btn" onclick="fmUploadFolder()" title="Папку целиком — в браузере, не в APK">⬆📁</button>
           <button class="btn" onclick="gitFmShow()" title="Ручной git: создать репо / коммит / push этой папки">📝 git</button>
           <button class="btn" onclick="fmOpenScreen()" title="Открыть на экране (вкладка Экран)">🖥</button>
           <div style="position:relative;margin-left:auto">
             <button class="btn btn-p" onclick="toggleFmMenu(event)">▶</button>
             <div class="apply-menu" id="fm-apply-menu"></div>
