         <div class="fm-transfer" id="fm-transfer" style="margin-top:8px;display:none;background:var(--bg2);border:1px solid var(--bdr);border-radius:8px;padding:8px;font-size:11px;color:var(--t3)">
           <div id="fm-transfer-name"></div>
           <div style="margin-top:4px;height:6px;border-radius:3px;background:var(--bdr);overflow:hidden"><div id="fm-transfer-bar" style="height:100%;width:0%;background:#58a6ff"></div></div>
           <div style="margin-top:4px"><span id="fm-transfer-progress"></span> · <span id="fm-transfer-speed"></span>/s · осталось <span id="fm-transfer-time"></span></div>
           <div style="margin-top:4px"><span id="fm-transfer-transferred"></span><span id="fm-transfer-total"></span></div>
         </div>
       </div>

 <!-- LINUX DESKTOP (VNC) — ОДИН ЭКРАН ДЛЯ ВСЕГО (RDP/VNC) -->
       <div class="page" id="p-linux" style="padding:0;flex-direction:column;height:100%">
         <!-- Одна тонкая строка: только управление экраном. Адрес, звук, починка —
              во вкладке «Настройки» (p-screen-settings). Экран — экран, не панель. -->
         <div class="linux-bar">
           <span id="linux-status" class="tag">…</span>
           <button class="btn btn-sm" onclick="linuxKeyboard()" title="Клавиатура телефона (в YouTube: k — пуск/пауза, f — во весь экран, m — звук)">⌨</button>
           <button class="btn btn-sm" id="linux-zoom-btn" onclick="linuxZoomToggle()" title="Заполнить / весь стол / 1:1">🔎</button>
           <button class="btn btn-sm" id="linux-perf-btn" onclick="linuxPerfToggle()" title="Плавность: плавно / баланс / чётко">⚡</button>
           <button class="btn btn-sm" id="linux-mouse-btn" onclick="linuxMouseToggle()" title="Виртуальная мышь: сенсор, две кнопки, колесо стрелками">🖱</button>
           <button class="btn btn-sm" onclick="linuxFullscreen()" title="На весь экран + поворот в ландшафт">⛶</button>
           <span id="linux-note"></span>
         </div>
         <style>
           /* ⛶ — экран на весь экран без потери noVNC-сессии.
              100dvh: на мобильных адресная строка Safari/Chrome иначе «съедает»
              часть высоты и картинка не заполняет экран. */
           #p-linux.linux-full{position:fixed!important;inset:0!important;height:100vh!important;height:100dvh!important;z-index:99999;background:#000}
           #p-linux.linux-full > .linux-bar, #p-linux.linux-full > #linux-more{display:none!important}
           /* «Просто рабочий стол»: на странице «Экран» не нужна шапка приложения —
              уйти можно нижним меню, а в полном экране есть ✕. */
           body.pg-linux .topbar{display:none}
           .linux-bar{display:flex;gap:6px;padding:6px 8px;background:var(--bg1);border-bottom:1px solid var(--bdr);flex-shrink:0;align-items:center;flex-wrap:nowrap;overflow:hidden}
           .linux-bar #linux-note{font-size:10px;color:var(--t3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
           #linux-more{display:flex;gap:6px;padding:6px 8px;background:var(--bg2);border-bottom:1px solid var(--bdr);flex-shrink:0;flex-wrap:wrap;align-items:center}
           #linux-more[hidden]{display:none}
           #linux-read{display:flex;gap:6px;align-items:center;flex-wrap:wrap;width:100%}
           #p-linux.linux-full #linux-stack{flex:1 1 auto;height:100%}
           /* В полном экране тулбары скрыты, поэтому клавиатура, масштаб и
              выход живут здесь — иначе за клавиатурой приходилось выходить из
              полноэкранного режима (на это и жаловались). */
           .linux-fsctl{display:none}
           #p-linux.linux-full .linux-fsctl{display:flex;gap:8px;position:absolute;top:10px;right:10px;z-index:100000}
           #p-linux.linux-full .linux-fsctl button{
             background:rgba(13,17,23,.8);color:#e6edf3;border:1px solid rgba(240,246,252,.25);
             border-radius:50%;width:40px;height:40px;font-size:16px;line-height:1}
           @media (max-width:560px){ .linux-hint{display:none!important} }
           /* ── Виртуальная мышь ──────────────────────────────────────────────
              Палец по картинке — плохой курсор: он закрывает то место, куда
              целишься, промах по мелкой кнопке уходит в пустоту, а скролл
              вообще некуда деть. Поэтому мышь отдельная: слева сенсор, справа
              ЛКМ/ПКМ, в центре колесо стрелками. */
           #linux-mouse{position:absolute;left:0;right:0;bottom:0;z-index:99990;display:flex;gap:8px;align-items:stretch;
             padding:8px;background:linear-gradient(180deg,rgba(13,17,23,.78),rgba(13,17,23,.95));
             border-top:1px solid rgba(240,246,252,.18);backdrop-filter:blur(6px);
             touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
           #linux-mouse[hidden]{display:none}
           .lm-pad{flex:1 1 auto;min-width:96px;min-height:104px;border-radius:12px;border:1px dashed rgba(240,246,252,.28);
