 function kickReconnect() {
   tabs.forEach(t => {
     if (t.manualClose) return;
     const s = t.ws;
     if (s && (s.readyState === WebSocket.OPEN || s.readyState === WebSocket.CONNECTING)) return;
     if (t.reconnectTimer) { clearTimeout(t.reconnectTimer); t.reconnectTimer = null; }
