   server.includes('handoff.noteActivity();') && server.includes("handoff.json"));
 check('q84 the successor run is not cancelled by the old one', hubWorkflow.includes('handoff:') &&
   hubWorkflow.includes('handoff_from:') &&
   hubWorkflow.includes('cancel-in-progress: ${{ inputs.replace && !inputs.handoff }}') &&
   hubWorkflow.includes('handoff-done') && server.includes("'handoff-done'") &&
   server.includes('handoff: true'));
 check('q85 handoff UI in both hubs and the panel', [mob, desk].every(x =>
   x.includes('function handoffRender()') && x.includes('function handoffSave()') &&
   x.includes('function handoffStart()') && x.includes('function handoffContinue()') &&
   x.includes('handoffPollStart()')) &&
   panel.includes('function handoffPanelSave()') && panel.includes('handoff.json') &&
   panel.includes('handoffPanelPoll()'));
 check('q86 big files travel as chunks', backupWork.includes('collect_big_files()') &&
   backupWork.includes('WORK_BACKUP_MAX_BIG_MB:-200') && backupWork.includes('WORK_BACKUP_CHUNK_MB:-20') &&
   backupWork.includes('"big": os.path.isdir') && restoreWork.includes('chunked big files') &&
   restoreWork.includes('sha256'));

 // q87: the branch is sorted into folders instead of one pile in the root.
 // publish_session.sh is the single place that decides where a file lands, so the
 // whole layout is asserted there.
 const migrateState = fs.readFileSync(path.join(__dirname, '..', 'tools', 'migrate_session_state.sh'), 'utf8');
 check('q87 session-state is split into folders', publishSession.includes('FILE="live/session.json"') &&
   publishSession.includes('slot=hub-linux)      FILE="live/session-hub-linux.json"') &&
   publishSession.includes("printf 'models/%s'") && publishSession.includes("printf 'snapshots/%s'") &&
   publishSession.includes("printf 'live/%s'") && publishSession.includes("printf 'history/%s/saved-%s'") &&
   publishSession.includes('FILE="history/$bucket/run-$_num.json"'));
 check('q88 history is filed by day and weekday', publishSession.includes('history_bucket()') &&
   publishSession.includes("date -u -d \"$d\" '+%a'") && publishSession.includes('Mon|Tue|Wed|Thu|Fri|Sat|Sun'));
 // q89: every reader looks in the new folder first and falls back to the old
 // root, so a branch that was never migrated keeps working.
 check('q89 readers fall back to the old layout', panel.includes('async function liveStatePath(') &&
   panel.includes('`live/${name}`, name') &&
   fs.readFileSync(path.join(__dirname, '..', 'app/src/main/assets/panel/desks.html'), 'utf8')
     .includes('`live/session-${slot}.json`') &&
   fs.readFileSync(path.join(__dirname, '..', 'hub/src/main/assets/hub/index.html'), 'utf8')
     .includes("'live/session-hub-linux.json'") &&
   server.includes("HANDOFF_FILE = 'live/handoff.json'") &&
   server.includes('HANDOFF_FILE_LEGACY') &&
   handoffSh.includes('live/session-$SLOT.json') &&
   restoreAudit.includes('pick_state_file()') && restoreAudit.includes('history_files()'));
 // q90: every session workflow ends by recording the run - when it started, how it
 // ended - so the history survives GitHub pruning the run list.
 const journalSteps = sessionWorkflows.every(x => x.includes('Record the run in the history') &&
   x.includes('journal=1') && x.includes('conclusion=${{ job.status }}'));
 check('q90 every session run is recorded', journalSteps && hubWorkflow.includes('journal_date=') &&
   panel.includes('function renderRunJournal(') && panel.includes('SESSION_RUN_NAMES') &&
   panel.includes("history/&lt;дата&gt;/&lt;день&gt;/run-N.json"));
 // q91: the one-time migration moves the old flat files and is safe to re-run.
 check('q91 migration tool', migrateState.includes('move "$f" "live/$f"') &&
   migrateState.includes('move "$f" "models/$f"') && migrateState.includes('move "$f" "snapshots/$f"') &&
   migrateState.includes('history/$day/$wd/saved-$base') &&
   migrateState.includes('nothing to migrate'));

 // q92: the handover log says WHAT was in flight, not only that a push happened,
 // and the resume report is the thing that can say it (read-only on a live db).
 const resumeReport = fs.readFileSync(path.join(__dirname, '..', 'tools', 'session_resume_report.sh'), 'utf8');
 check('q92 handover log carries the resume report', handoffSh.includes('session_resume_report.sh') &&
   handoffSh.includes('2>&1 | tee -a "$HUB_LOGS/handoff.log" || true') &&
   resumeReport.includes('mode=ro') && resumeReport.includes('parent_id IS NULL') &&
   resumeReport.includes('AGENT_SESSION.md') && resumeReport.includes('--json'));

 // q93: a snapshot that GitHub refuses must never pass for a backup. The live
 // branch collected latest.json updates for two days while every snapshot was
 // rejected as an oversized blob - the log said "published" every 5 minutes.
 check('q93 oversized blobs are split before the push', backupWork.includes('split_big_blobs()') &&
   backupWork.includes('WORK_BACKUP_MAX_BLOB_MB:-80') &&
   backupWork.includes("'blobs', str(index)") &&
   backupWork.includes('big-blobs.json') &&
   backupWork.includes('refused (a file over 100 MB is the usual reason)') &&
   backupWork.includes('git ls-remote origin "refs/heads/$BRANCH"') &&
   restoreWork.includes('rebuild_split_blobs()') &&
   restoreWork.includes("'blobs', str(n)") && restoreWork.includes('sha256 mismatch'));
 check('q94 a push without a snapshot is a failure', backupWork.includes('verify_published()') &&
   backupWork.includes('PUBLISH VERIFIED AS EMPTY') &&
   backupWork.includes('if [ "$pushed" = 1 ] && ! verify_published "$stamp"; then') &&
   backupWork.includes('return 3') && backupWork.includes('NOTHING LANDED') &&
   backupWork.includes('[ "$publish_status" -eq 3 ]'));

 // q95: a shallow clone has no usable bundle, so its committed tree travels as
 // an archive - and a bundle that will not clone must not lose the repository.
 check('q95 shallow repositories are archived', backupWork.includes('--is-shallow-repository') &&
   backupWork.includes('worktree.tar.gz') && backupWork.includes('worktree archive failed') &&
   backupWork.includes(':(exclude)*.apk') && backupWork.includes('"shallow": shallow') &&
   restoreWork.includes('rebuild_from_archive()') &&
   restoreWork.includes('if python3 - "$snap" <<') &&
   restoreWork.includes('GIT_AUTHOR_NAME="Restore"') &&
   restoreWork.includes('if rebuild_from_archive "$repodir" "$dest" "$rel"'));
 // q96: builds and re-downloadable payloads stay out, and the log says so.
 check('q96 build products are left out by design', backupWork.includes("'*.apk' '*.aab' '*.apks'") &&
   backupWork.includes("'*/.dotnet/tools/.store/*'") &&
   backupWork.includes('left out by design') &&
   backupWork.includes('*/.opencode/*'));

 // q97: a wedged runner is reachable again (Z10). Two lifelines outlive any
 // dead hub/tunnel: a tmate SSH/web shell published to control/rescue.json and
 // a whitelisted command queue on control/queue.json - and the watchdog's
 // cleanup kills them like the older daemons so cancel stays fast.
 const hubControl = fs.readFileSync(path.join(__dirname, '..', 'tools/hub_control.sh'), 'utf8');
 const rescueSsh = fs.readFileSync(path.join(__dirname, '..', 'tools/rescue_ssh.sh'), 'utf8');
 check('q97 runner rescue channels: tmate ssh + command queue',
   hubWorkflow.includes('rescue_ssh') && hubWorkflow.includes('command_queue') &&
   hubWorkflow.includes('tools/rescue_ssh.sh') && hubWorkflow.includes('tools/hub_control.sh') &&
   hubWorkflow.includes('pkill -f "[h]ub_control.sh"') && hubWorkflow.includes('tmate -S "$HUB_LOGS/tmate.sock" kill-session') &&
   hubControl.includes('backup-now') && hubControl.includes('restart-hub') &&
   hubControl.includes('restart-tunnel') && hubControl.includes('handoff-save') &&
   hubControl.includes('control/queue.json') && hubControl.includes('control/results/') &&
   !hubControl.includes('eval ') &&
   rescueSsh.includes("#{tmate_ssh}") && rescueSsh.includes('control/rescue.json'));

 console.log(`MOBILE-TOUCH: ${pass} passed, ${fail} failed`);
 process.exit(fail ? 1 : 0);

