Index: tests/term-mouse-test.js
===================================================================
--- tests/term-mouse-test.js	
+++ tests/term-mouse-test.js	
@@ -0,0 +1,182 @@
+// Живая проверка term-mouse.js в jsdom: полоса строится, колесо/мышь уходят
+// в term.element (а не в PTY мимо xterm), режим мыши читается из вывода.
+const fs = require('fs');
+const path = require('path');
+const { JSDOM } = require(path.join(__dirname, 'node_modules', 'jsdom'));
+
+const src = fs.readFileSync(path.join(__dirname, '..', 'npm-hub', 'public', 'term-mouse.js'), 'utf8');
+
+let pass = 0, fail = 0;
+function check(name, cond, extra) {
+  if (cond) { pass++; console.log('PASS ' + name); }
+  else { fail++; console.log('FAIL ' + name + (extra !== undefined ? ' got=' + JSON.stringify(extra) : '')); }
+}
+
+const dom = new JSDOM(`<!doctype html><html><body>
+  <div class="term-wrap" id="wrap">
+    <div class="term" id="termEl"></div>
+  </div>
+</body></html>`, { pretendToBeVisual: true, runScripts: 'outside-only', url: 'https://hub.local/term' });
+
+const { window } = dom;
+global.window = window;
+window.eval(src);
+
+const wrap = window.document.getElementById('wrap');
+const termEl = window.document.getElementById('termEl');
+
+// Следим за тем, что реально долетает до xterm.
+const seen = [];
+const termElX = window.document.createElement('div');
+termElX.className = 'xterm';
+const screen = window.document.createElement('div');
+screen.className = 'xterm-screen';
+termElX.appendChild(screen);
+termEl.appendChild(termElX);
+// jsdom не рисует: задаём геометрию сами — 80×24 клетки по 10×20 px.
+function rect(left, top, width, height) {
+  return { left, top, width, height, right: left + width, bottom: top + height, x: left, y: top };
+}
+screen.getBoundingClientRect = () => rect(0, 0, 800, 480);
+termEl.getBoundingClientRect = () => rect(0, 0, 800, 480);
+termElX.getBoundingClientRect = () => rect(0, 0, 800, 480);
+wrap.getBoundingClientRect = () => rect(0, 0, 800, 480);
+['mousedown', 'mouseup', 'mousemove', 'wheel'].forEach(t =>
+  termElX.addEventListener(t, (e) => seen.push({ t, button: e.button, buttons: e.buttons, deltaY: e.deltaY, deltaX: e.deltaX })));
+
+// xterm-подделка: cols/rows + методы, которые зовёт модуль.
+let wrote = [];
+const term = {
+  cols: 80, rows: 24, element: termElX,
+  buffer: { active: { type: 'normal' }, onBufferChange: () => ({ dispose() {} }) },
+  write(d, cb) { wrote.push(d); if (cb) cb(); },
+  scrollLines(n) { seen.push({ t: 'scrollLines', n }); }
+};
+
+const st = window.TermMouse.mount({ wrap, termEl, term, send: (d) => seen.push({ t: 'send', d }) });
+check('mount returns a handle', !!st && typeof st.upd === 'function' && typeof st.destroy === 'function');
+check('bar is in the terminal', !!wrap.querySelector('.tmouse'));
+check('cursor mark is in the terminal', !!wrap.querySelector('.tm-mark'));
+const pad = wrap.querySelector('.tm-pad');
+const l = wrap.querySelector('[data-btn="1"]');
+const r = wrap.querySelector('[data-btn="4"]');
+check('bar has pad, two buttons and four arrows',
+  !!pad && !!l && !!r &&
+  ['up', 'down', 'left', 'right'].every(d => !!wrap.querySelector(`[data-dir="${d}"]`)));
+check('buttons are dimmed while the app has no mouse',
+  l.classList.contains('dim') && r.classList.contains('dim'));
+
+function pev(el, type, x, y, extra) {
+  const e = new window.PointerEvent(type, Object.assign({
+    bubbles: true, cancelable: true, pointerId: 1, clientX: x, clientY: y, isPrimary: true
+  }, extra || {}));
+  el.dispatchEvent(e);
+  return e;
+}
+
+// 1. Тяга по сенсору = колесо.
+pev(pad, 'pointerdown', 100, 100);
+pev(pad, 'pointermove', 100, 160);
+pev(pad, 'pointerup', 100, 160);
+check('pad drag is a wheel', seen.some(s => s.t === 'wheel' && s.deltaY > 0), seen);
+
+// 2. Тап по сенсору = шаг (вверх по верхней половине, вниз по нижней).
+seen.length = 0;
+pev(pad, 'pointerdown', 100, 300);
+pev(pad, 'pointerup', 100, 300);
+check('pad tap is one wheel step down', seen.filter(s => s.t === 'wheel').length === 1 &&
+  seen[0].deltaY > 0, seen);
+
+// 3. Стрелки колеса крутятся и сами (удержание).
+seen.length = 0;
+pev(wrap.querySelector('[data-dir="up"]'), 'pointerdown', 10, 10);
+check('wheel arrow fires', seen.some(s => s.t === 'wheel' && s.deltaY < 0), seen);
+pev(wrap.querySelector('[data-dir="up"]'), 'pointerup', 10, 10);
+
+// 4. ЛКМ/ПКМ идут в xterm как настоящая мышь — но только когда её включил
+//    приложение, иначе кнопки не притворяются.
+seen.length = 0;
+pev(l, 'pointerdown', 10, 10);
+check('ЛКМ is silent without app mouse', !seen.some(s => s.t === 'mousedown'), seen);
+check('...and the bar says why while it is held',
+  /не включило/.test(pad.querySelector('.tm-hint').textContent),
+  pad.querySelector('.tm-hint').textContent);
+pev(l, 'pointerup', 10, 10);
+check('...and goes back to normal after release',
+  /тяни — колесо/.test(pad.querySelector('.tm-hint').textContent),
+  pad.querySelector('.tm-hint').textContent);
+
+// Приложение включило мышь (DECSET 1000 + 1006) — это видно в выводе.
+term.write('\x1b[?1049h\x1b[?1000h\x1b[?1006h');
+check('mouse mode seen in the output', st.mouseOn === true);
+check('buttons stop being dimmed', !l.classList.contains('dim') && !r.classList.contains('dim'));
+check('the app still got its bytes', wrote.length === 1);
+
+// 5. Теперь ЛКМ/ПКМ кликают, ПКМ — правой кнопкой, и тяга с зажатой ЛКМ
+//    тянет выделение.
+seen.length = 0;
+pev(l, 'pointerdown', 10, 10);
+check('ЛКМ press reaches xterm', seen.some(s => s.t === 'mousedown' && s.button === 0 && s.buttons === 1), seen);
+pev(pad, 'pointerdown', 100, 100);
+pev(pad, 'pointermove', 130, 130);
+check('drag with a held button moves the mouse', seen.some(s => s.t === 'mousemove' && s.buttons === 1), seen);
+pev(pad, 'pointerup', 130, 130);
+pev(l, 'pointerup', 10, 10);
+check('ЛКМ release reaches xterm', seen.some(s => s.t === 'mouseup' && s.buttons === 0), seen);
+
+seen.length = 0;
+pev(r, 'pointerdown', 10, 10);
+check('ПКМ is the right button', seen.some(s => s.t === 'mousedown' && s.button === 2 && s.buttons === 4), seen);
+pev(r, 'pointerup', 10, 10);
+
+// 6. Tab/⏎ идут в PTY напрямую.
+seen.length = 0;
+wrap.querySelector('[data-key="tab"]').dispatchEvent(new window.PointerEvent('pointerdown', { bubbles: true }));
+check('Tab goes to the PTY as a real control byte', seen.some(s => s.t === 'send' && s.d === '\t'), seen);
+seen.length = 0;
+wrap.querySelector('[data-key="enter"]').dispatchEvent(new window.PointerEvent('pointerdown', { bubbles: true }));
+check('Enter goes to the PTY as a real control byte', seen.some(s => s.t === 'send' && s.d === '\r'), seen);
+
+// 7. Наведение тапом по экрану: курсор встаёт в клетку под пальцем, а рамка
+//    на экране показывает, куда придётся ЛКМ.
+st.aim = { col: 0, row: 0 };
+function touch(type, x, y) {
+  const t = { clientX: x, clientY: y };
+  const e = new window.Event(type, { bubbles: true });
+  e.touches = type === 'touchend' ? [] : [t];
+  e.changedTouches = [t];
+  termEl.dispatchEvent(e);
+}
+touch('touchstart', 55, 45);
+touch('touchend', 55, 45);
+check('a tap aims the cursor', st.aim.col === 5 && st.aim.row === 2, st.aim);
+const mark = wrap.querySelector('.tm-mark');
+check('the cursor box follows the aim',
+  mark.style.left === '50px' && mark.style.top === '40px' &&
+  mark.style.width === '10px' && mark.style.height === '20px' && mark.style.display === 'block',
+  { l: mark.style.left, t: mark.style.top, w: mark.style.width, d: mark.style.display });
+// Свайп курсор не двигает — он листает.
+st.aim = { col: 5, row: 2 };
+touch('touchstart', 55, 45);
+touch('touchmove', 55, 200);
+touch('touchend', 55, 200);
+check('a swipe does not move the cursor', st.aim.col === 5 && st.aim.row === 2, st.aim);
+
+// 8. Скрытие полосы — на всех панелях сразу и запоминается.
+window.TermMouse.setEnabled(false);
+check('bar hides everywhere', wrap.querySelector('.tmouse').hidden === true);
+check('...and the flag is remembered', window.TermMouse.isEnabled() === false);
+window.TermMouse.toggle();
+check('toggle brings it back', wrap.querySelector('.tmouse').hidden === false &&
+  window.TermMouse.isEnabled() === true);
+
+// 9. Закрытие вкладки ничего не оставляет в DOM и не течёт подписками.
+st.destroy();
+check('destroy removes the bar', !wrap.querySelector('.tmouse') && !wrap.querySelector('.tm-mark'));
+seen.length = 0;
+window.dispatchEvent(new window.Event('resize'));
+pev(pad, 'pointerdown', 10, 10);
+check('destroy unsubscribes', seen.length === 0, seen);
+
+console.log(`TERM-MOUSE: ${pass} passed, ${fail} failed`);
+process.exit(fail ? 1 : 0);

