Let me now write term-mouse.js.

```js
/* =========================================================================
 * term-mouse.js — виртуальная мышь терминала (сенсор + ЛКМ/ПКМ + колесо).
 * ...
 */
```

Key functions. Let me write it out.

```js
(function (global) {
  'use strict';

  var SENS = 1.8;
  var WHEEL_LINE = 120;        // px за один щелчок колеса
  var WHEEL_REPEAT = 130;
  var TAP_SLOP = 10;
  var TAP_MS = 320;
  var DBL_MS = 320;
  var LS = 'hub_tmouse';
  var MODES_ON = /\x1b\[\?(?:1000|1002|1003|1016)[hl]/;   // hmm need value
  ...
```

Let me write the mode scanner:
```js
  var MODE_RE = /\x1b\[\?(1000|1002|1003|1005|1006|1015|1016)([hl])/g;
  function scanModes(st, data) {
    if (typeof data !== 'string' || data.indexOf('\x1b[?') < 0) return;
    MODE_RE.lastIndex = 0;
    var m, changed = false;
    while ((m = MODE_RE.exec(data))) {
      var on = m[2] === 'h';
      if (m[1] === '1000' || m[1] === '1002' || m[1] === '1003') { if (st.mouseOn !== on) { st.mouseOn = on; changed = true; } }
      if (m[1] === '1006' || m[1] === '1015') st.sgr = on || st.sgr;
    }
    if (changed) paint(st);
  }
```
Careful with `1005`/`1016` (UTF-8 vs urxvt). Keep it simple: track 1000/1002/1003 for "mouse enabled", and 1006 for SGR (only used for the note, not for encoding since xterm does the encoding).

Now the pad handlers.

```js
  function padDown(st, e) {
    if (st.drag) return;
    e.preventDefault();
    var t = point(e);
    st.drag = { x: t.x, y: t.y, t: Date.now(), moved: 0, aim: held(st) };
    st.pad.classList.add(st.drag.aim ? 'aim' : 'active');
    try { st.pad.setPointerCapture(e.pointerId); } catch (_) {}
  }
  function padMove(st, e) {
    var d = st.drag; if (!d) return;
    e.preventDefault();
    var t = point(e);
    var dx = t.x - d.x, dy = t.y - d.y;
    d.x = t.x; d.y = t.y; d.moved += Math.abs(dx) + Math.abs(dy);
    if (!dx && !dy) return;
    if (d.aim) { moveAim(st, dx * SENS, dy * SENS); dragMouse(st); }
    else wheel(st, dy, dx);
  }
  function padUp(st, e) {
    var d = st.drag; if (!d) return;
    e.preventDefault();
    st.drag = null;
    st.pad.classList.remove('active', 'aim');
    if (d.aim) return;                       // это было перетаскивание мышью
    if (d.moved >= TAP_SLOP || Date.now() - d.t > TAP_MS) return;
    // тап: верхняя половина — вверх, нижняя — вниз; два тапа — страница
    var r = st.pad.getBoundingClientRect();
    var up = t.y < r.top + r.height / 2;
    var now = Date.now();
    var dbl = now - st.lastTap < DBL_MS;
    st.lastTap = now;
    wheel(st, up ? -(dbl ? WHEEL_PAGE : WHEEL_STEP) : (dbl ? WHEEL_PAGE : WHEEL_STEP), 0);
  }
```

`wheel(st, dyLines, dxLines)`: dispatch a synthetic WheelEvent with deltaY = dyLines*WHEEL_LINE... hmm, careful: the pad drag accumulates dy in px; dispatching a wheel event per move with deltaY = dy*3 (like setupTermTouch's `fireWheel(dy*2)`) is smooth. For discrete steps, deltaY = ±120 (one notch-ish). Let me define:

```js
  function wheelAt(st, dy, dx) {
    // xterm сам решает: колесо приложению (vim/top) или прокрутка scrollback
    var el = st.term.element || st.termEl;
    if (!el) return false;
    var p = aimPoint(st);
    try {
      el.dispatchEvent(new WheelEvent('wheel', {
        bubbles: true, cancelable: true, composed: true, view: global,
        deltaY: dy, deltaX: dx || 0, deltaMode: 0,
        clientX: Math.round(p.x), clientY: Math.round(p.y)
      }));
      return true;
    } catch (_) { return false; }
  }
```
And a fallback if it returns false: `st.term.scrollLines(-Math.sign(dy))`. Hmm — if the dispatch throws (no WheelEvent ctor), fall back to `term.scrollLines`. Also: if the event dispatched but the normal buffer had nothing to scroll, xterm's `handleWheel` returns false and nothing happens (correct). Don't force scrollLines in alt mode. So: only use scrollLines when the dispatch *fails*. And scrollLines direction: `term.scrollLines(-1)` scrolls up (decreases ydisp). Our dy>0 means "content moves up = scroll down" → `scrollLines(-Math.sign(dy))`. Let me double check xterm's `scrollLines(disp)`: `BufferService.scrollLines(amount)` → `this._buffer.ydisp += amount` clamped to [0, baseY]. So `scrollLines(-1)` moves the viewport up (older content). Wheel deltaY>0 (scroll down) should show newer content = increase ydisp = `scrollLines(+1)`. So `scrollLines(Math.sign(dy))`. Let me verify with the arrow-key path: in alt-buffer mode xterm sends ESC[A for deltaY<0 (scroll up) and ESC[B for deltaY>0. In a pager, ESC[A (up arrow) shows older content. So deltaY>0 → newer → ydisp increases → `scrollLines(+1)`. ✓ `scrollLines(Math.sign(dy))`.

Mouse press/release/move:

```js
  function mouseAt(st, type, button, buttons) {
    var el = st.term.element || st.termEl;
    if (!el) return false;
    var p = aimPoint(st);
    try {
      el.dispatchEvent(new MouseEvent(type, {
        bubbles: true, cancelable: true, composed: true, view: global,
        clientX: Math.round(p.x), clientY: Math.round(p.y),
        button: button, buttons: buttons
      }));
      return true;
    } catch (_) { return false; }
  }
```

Buttons:
```js
  function btnDown(st, mask) {
    st.held[mask] = true;
    st.btn[mask].classList.add('on');
    if (!st.mouseOn) { hint(st, 'приложение мышь не включило — ЛКМ/ПКМ молчат'); return; }
    mouseAt(st, 'mousedown', mask === 4 ? 2 : 0, mask);
  }
  function btnUp(st, mask) {
    if (!st.held[mask]) return;
    st.held[mask] = false;
    st.btn[mask].classList.remove('on');
    if (!st.mouseOn) return;
    mouseAt(st, 'mouseup', mask === 4 ? 2 : 0, 0);
  }
```
And while held, the pad drag sends `mousemove` with `buttons = mask`.

`aim` handling:
```js
  function aimCell(st) { return st.aim; }  // {col,row} row is absolute buffer row
  function aimRect(st) {  // client rect of the aimed cell
    var screen = st.term.element && st.term.element.querySelector('.xterm-screen');
    if (!screen) return null;
    var r = screen.getBoundingClientRect();
    if (!r.width || !r.height || !st.term.cols || !st.term.rows) return null;
    var cw = r.width / st.term.cols, ch = r.height / st.term.rows;
    var view = Math.max(0, Math.min(st.term.rows - 1, (st.aim.row - viewportY())));
    return { left: r.left + st.aim.col * cw, top: r.top + view * ch, w: cw, h: ch };
  }
```
Hmm, `st.aim.row` — do I want the absolute buffer row or the viewport row? Mouse reporting uses 1-based *viewport* coordinates (what's on screen). The buffer row matters only for re-anchoring after the view scrolls. Simplest: store the aim as a **viewport cell** (row within the visible screen) at the moment of aiming. Then the mouse coordinate is direct, and the mark follows the screen position — but after scrolling, the mark would point at whatever scrolls under it, which is exactly what a real mouse does (the mouse stays at a screen position). ✓ Correct semantics! Real mouse = screen position, not buffer position.

So: `st.aim = {col, row}` with row in [0, rows-1] (screen row). Moving the aim with a drag: col += dx/cw, row += dy/ch, clamped. Need cw/ch: from the screen rect. Store them at aim time and refresh on each use (`metrics(st)`).

`paint(st)` positions `.tm-mark` and updates the hint + button dim.

`tap to aim`:
```js
  function tapAim(st, x, y) {
    var m = metrics(st); if (!m) return;
    var col = clamp(Math.floor((x - m.left) / m.cw), 0, st.term.cols - 1);
    var row = clamp(Math.floor((y - m.top) / m.ch), 0, st.term.rows - 1);
    st.aim = { col: col, row: row };
    paint(st);
  }
```
Listeners on `st.termEl`:
```js
  st.termEl.addEventListener('touchend', (e) => {
    var t = e.changedTouches && e.changedTouches[0]; if (!t) return;
    if (e.touches && e.touches.length) return;      // палец всё ещё на экране
    if (st.touchMoved) { st.touchMoved = false; return; }
    if (Date.now() - st.touchStart > 700) return;
    tapAim(st, t.clientX, t.clientY);
  }, { passive: true });
  st.termEl.addEventListener('touchstart', (e) => { st.touchStart = Date.now(); st.touchMoved = false; }, {passive:true});
  st.termEl.addEventListener('touchmove', () => { st.touchMoved = true; }, {passive:true});
  st.termEl.addEventListener('mousedown', (e) => { if (e.button === 0) tapAim(st, e.clientX, e.clientY); });
```
Hmm, `touchmove` sets touchMoved on ANY move, including tiny ones. Use a threshold:
```js
  st.termEl.addEventListener('touchstart', (e) => { const t = e.touches[0]; st.tap = {x:t.clientX, y:t.clientY, t:Date.now(), moved:0}; }, {passive:true});
  st.termEl.addEventListener('touchmove', (e) => { if (st.tap) { const t = e.touches[0]; st.tap.moved += Math.abs(t.clientX - st.tap.x) + Math.abs(t.clientY - st.tap.y); st.tap.x = t.clientX; st.tap.y = t.clientY; } }, {passive:true});
  st.termEl.addEventListener('touchend', (e) => {
    const p = st.tap; st.tap = null; if (!p) return;
    if (p.moved > 12 || Date.now() - p.t > 700) return;
    const t = e.changedTouches[0]; if (!t) return;
    tapAim(st, t.clientX, t.clientY);
  }, {passive:true});
```

Also the `contextmenu` on the terminal (right-click on desktop) → aim + ПКМ press/release? Nice touch: `st.termEl.addEventListener('contextmenu', e => tapAim(...))`. But `setupTermTouch` already preventDefaults the contextmenu and selects a word. Fine, just set the aim.

Now the global toggle:
```js
  function setEnabled(on) {
    enabled = !!on;
    try { localStorage.setItem(LS, enabled ? '1' : '0'); } catch (_) {}
