/* =========================================================================
 * term-mouse.js — виртуальная мышь терминала: СЕНСОР + ЛКМ/ПКМ + колесо.
 *
 * Полоса та же, что на вкладке «Экран» (lm-* в mobile.html), привод другой:
 * у терминала нет рабочего стола, поэтому
 *   СЕНСОР — колесо мыши. Событие уходит в xterm, и он сам решает: листать
 *           свой scrollback или отдать колесо приложению на alternate-буфере
 *           (vim, top, less, opencode). Тап = шаг, два тапа = страница.
 *   ЛКМ/ПКМ — настоящие mousedown/mouseup в клетке, на которую наведён
 *           виртуальный курсор: тап по экрану наводит, зажатая кнопка плюс
 *           тяга по сенсору тянет выделение (как настоящая мышь).
 *   ▲▼◀▶   — колесо; при удержании повторяется само.
 *
 * Мышиные события намеренно НЕ кодируются вручную в SGR/X10: они
 * отправляются в term.element, и xterm сам решает, отдать их приложению
 * (DECSET 1000/1002/1003 + 1006) или проглотить. Поэтому ЛКМ/ПКМ не
 * превращаются в мусор в обычном шелле и не «висят» там, где мышь не
 * включена, — про это честно говорит подпись под сенсором.
 *
 * Один файл на все три страницы (панель, десктоп, /term): три копии
 * расходились, и старая полоса в term-app.js тихо работала иначе.
 * ========================================================================= */
(function (global) {
  'use strict';

  var SENS = 1.8;          // палец прошёл 10 px — курсор 18 px экрана
  var WHEEL = 120;         // px за один щелчок колеса
  var PAGE = 560;          // «страница» (два тапа по сенсору)
  var REPEAT = 130;        // мс между щелчками, пока стрелку держат
  var SLOP = 10;           // меньше — тап, больше — тяга
  var TAP_MS = 340;
  var DBL_MS = 340;
  var LS_KEY = 'hub_tmouse';

  var bars = [];           // живые панели: {bar, pad, ...}
  var enabled = readFlag();

  function readFlag() {
    try {
      var v = localStorage.getItem(LS_KEY);
      // По умолчанию включено: старая полоса тоже висела всегда, а без неё
      // в терминале на телефоне нет ни прокрутки, ни кнопок мыши.
      return v === null ? true : v === '1';
    } catch (e) { return true; }
  }

  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }

  // ── геометрия: экран терминала ↔ клетки ─────────────────────────────────
  // Размеры берём из .xterm-screen: он всегда равен cols×rows, поэтому
  // размер шрифта и devicePixelRatio знать не надо.
  function metrics(st) {
    var screen = st.term && st.term.element && st.term.element.querySelector('.xterm-screen');
    if (!screen || !st.term.cols || !st.term.rows) return null;
    var r = screen.getBoundingClientRect();
    if (!r.width || !r.height) return null;
    return { left: r.left, top: r.top, cw: r.width / st.term.cols, ch: r.height / st.term.rows };
  }

  function defaultAim(st) {
    var m = metrics(st);
    if (!m) return null;
    return { col: Math.floor(st.term.cols / 2), row: Math.floor(st.term.rows / 2) };
  }

  function aim(st) {
    if (!st.aim) st.aim = defaultAim(st);
    return st.aim;
  }

  // Клетка, на которую поведен курсор, в координатах экрана: там же их ждёт
  // xterm (он сам пересчитывает их в отчёт для приложения).
  function aimPoint(st) {
    var a = aim(st), m = metrics(st);
    if (!a || !m) {
      var el = st.term && st.term.element;
      if (el) { var r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; }
      return { x: 0, y: 0 };
    }
    return { x: m.left + (a.col + 0.5) * m.cw, y: m.top + (a.row + 0.5) * m.ch };
  }

  // ── синтетические события: путь ровно через xterm ─────────────────────────
  function target(st) {
    return (st.term && st.term.element) || st.termEl;
  }

  function sendWheel(st, dy, dx) {
    var el = target(st);
    if (!el) return false;
    var p = aimPoint(st);
    try {
      el.dispatchEvent(new WheelEvent('wheel', {
        bubbles: true, cancelable: true, composed: true, view: global,
        deltaY: dy, deltaX: dx || 0, deltaMode: 0,
        clientX: Math.round(p.x), clientY: Math.round(p.y)
      }));
      return true;
    } catch (e) { return false; }
  }

  // Колесо одним шагом: сначала событие (xterm знает про alternate-буфер и
  // про включённую мышь приложения), а если событие построить не удалось —
  // его собственный scrollLines, чтобы листание не пропало вовсе.
  function wheel(st, lines) {
    if (!lines) return;
    if (sendWheel(st, lines > 0 ? WHEEL : -WHEEL, 0)) return;
    try { st.term.scrollLines(lines > 0 ? 1 : -1); } catch (e) {}
  }

  function sendMouse(st, type, button, buttons) {
    var el = target(st);
    if (!el) return false;
    var p = aimPoint(st);
    try {
      el.dispatchEvent(new MouseEvent(type, {
        bubbles: true, cancelable: true, composed: true, view: global,
        clientX: Math.round(p.x), clientY: Math.round(p.y),
        button: button || 0, buttons: buttons || 0
      }));
      return true;
    } catch (e) { return false; }
  }

  // ── состояние панели ─────────────────────────────────────────────────────
  function setAimFrom(st, clientX, clientY) {
    var m = metrics(st);
    if (!m) return;
    st.aim = {
      col: clamp(Math.floor((clientX - m.left) / m.cw), 0, st.term.cols - 1),
      row: clamp(Math.floor((clientY - m.top) / m.ch), 0, st.term.rows - 1)
    };
    paint(st);
  }

  function moveAim(st, dx, dy) {
    var m = metrics(st), a = aim(st);
    if (!m || !a) return;
    a.col = clamp(a.col + Math.round(dx / m.cw), 0, st.term.cols - 1);
    a.row = clamp(a.row + Math.round(dy / m.ch), 0, st.term.rows - 1);
  }

  function heldMask(st) {
    return (st.held[1] ? 1 : 0) | (st.held[4] ? 4 : 0);
  }

  function buttonDown(st, mask) {
    st.held[mask] = true;
    var b = st.btn[mask];
    if (b) b.classList.add('on');
    st.mark.classList.add('on');
    if (!st.mouseOn) { note(st, 'приложение мышь не включило — ЛКМ/ПКМ молчат'); return; }
    sendMouse(st, 'mousedown', mask === 4 ? 2 : 0, mask);
  }

  function buttonUp(st, mask) {
    if (!st.held[mask]) return;
    st.held[mask] = false;
    var b = st.btn[mask];
    if (b) b.classList.remove('on');
    if (!heldMask(st)) st.mark.classList.remove('on');
    if (!st.mouseOn) return;
    sendMouse(st, 'mouseup', mask === 4 ? 2 : 0, 0);
  }

  function note(st, text) {
    if (!st.hint) return;
    st.hint.textContent = text;
    st.hint.classList.toggle('warn', /не включило/.test(text));
  }

  // Курсор живёт поверх экрана: он показывает, куда придётся ЛКМ/ПКМ.
  function paint(st) {
    if (st.mark) {
      var a = aim(st), m = metrics(st);
      if (a && m) {
        var wrap = st.wrap.getBoundingClientRect();
        st.mark.style.left = (m.left + a.col * m.cw - wrap.left) + 'px';
        st.mark.style.top = (m.top + a.row * m.ch - wrap.top) + 'px';
        st.mark.style.width = m.cw + 'px';
        st.mark.style.height = m.ch + 'px';
        st.mark.style.display = '';
      } else {
        st.mark.style.display = 'none';
      }
    }
    // Тусклим стрелки, если в их сторону крутить некуда: на alternate-буфере
    // (vim, top) колесо уходит приложению, там предела нет.
    if (st.arr.up && st.arr.down) {
      var alt = isAlt(st);
      var vp = st.vp;
      if (alt || !vp) {
        st.arr.up.classList.remove('dim');
        st.arr.down.classList.remove('dim');
      } else {
        var max = vp.scrollHeight - vp.clientHeight;
        st.arr.up.classList.toggle('dim', max <= 0 || vp.scrollTop <= 0);
        st.arr.down.classList.toggle('dim', max <= 0 || vp.scrollTop >= max - 1);
      }
    }
    if (st.btn[1]) st.btn[1].classList.toggle('dim', !st.mouseOn);
    if (st.btn[4]) st.btn[4].classList.toggle('dim', !st.mouseOn);
  }

  function isAlt(st) {
    try {
      var b = st.term && st.term.buffer && st.term.buffer.active;
      return !!(b && b.type === 'alternate');
    } catch (e) { return false; }
  }

  // ── сенсор ───────────────────────────────────────────────────────────────
  // Тяга = колесо. Но если ЛКМ/ПКМ зажата — та же тяга ведёт курсор, то есть
  // выделяет текст в приложении: ровно как перетаскивание настоящей мышью.
  function padDown(st, e) {
    if (st.drag) return;
    var t = pointOf(e);
    st.drag = { x: t.x, y: t.y, at: Date.now(), moved: 0, aim: !!heldMask(st) };
    st.pad.classList.add(st.drag.aim ? 'aim' : 'active');
    try { if (e.pointerId !== undefined) st.pad.setPointerCapture(e.pointerId); } catch (err) {}
    try { e.preventDefault(); } catch (err) {}
  }

  function padMove(st, e) {
    var d = st.drag;
    if (!d) return;
    var t = pointOf(e);
    var dx = t.x - d.x, dy = t.y - d.y;
    d.x = t.x; d.y = t.y;
    d.moved += Math.abs(dx) + Math.abs(dy);
    try { e.preventDefault(); } catch (err) {}
    if (!dx && !dy) return;
    if (d.aim) {
      moveAim(st, dx * SENS, dy * SENS);
      if (st.mouseOn && heldMask(st)) sendMouse(st, 'mousemove', 0, heldMask(st));
      paint(st);
    } else {
      wheel(st, (dy * 2) / WHEEL);
    }
  }

  function padUp(st, e) {
    var d = st.drag;
    if (!d) return;
    st.drag = null;
    st.pad.classList.remove('active', 'aim');
    try { e.preventDefault(); } catch (err) {}
    if (d.aim) return;                                  // это была тяга мышью
    if (d.moved >= SLOP || Date.now() - d.at > TAP_MS) return;
    // Тап: верхняя половина сенсора — вверх, нижняя — вниз; два тапа — страница.
    var r = st.pad.getBoundingClientRect();
    var up = pointOf(e).y < r.top + r.height / 2;
    var now = Date.now();
    var dbl = now - st.lastTap < DBL_MS;
    st.lastTap = now;
    wheel(st, (up ? -1 : 1) * (dbl ? PAGE / WHEEL : 1));
  }

  function pointOf(e) {
    var t = (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]) || e;
    return { x: t.clientX || 0, y: t.clientY || 0 };
  }

  // ── колесо стрелками ─────────────────────────────────────────────────────
  function wheelStart(st, dir) {
    wheelStop(st);
    var sign = dir === 'up' ? -1 : (dir === 'down' ? 1 : 0);
    var dsign = dir === 'left' ? -1 : (dir === 'right' ? 1 : 0);
    var fire = function () {
      if (sign) wheel(st, sign);
      else if (dsign) {
        // Горизонтальное колесо есть не у всех приложений, но там, где есть
        // (широкие списки, панели), оно нужно — и xterm отдаёт его как есть.
        if (!sendWheel(0, dsign * WHEEL)) { try { st.term.scrollLines(0); } catch (e) {} }
      }
    };
    fire();
    st.wheelTimer = setInterval(fire, REPEAT);
    var b = st.arr[dir];
    if (b) b.classList.add('on');
  }

  function wheelStop(st) {
    if (st.wheelTimer) { clearInterval(st.wheelTimer); st.wheelTimer = null; }
    if (!st.arr) return;
    for (var k in st.arr) st.arr[k].classList.remove('on');
  }

  // ── полоса ───────────────────────────────────────────────────────────────
  function build(st) {
    var bar = document.createElement('div');
    bar.className = 'tmouse';
    bar.innerHTML =
      '<div class="tm-pad"><span class="tm-hint">СЕНСОР · тяни — колесо, тап — шаг, два тапа — страница</span></div>' +
      '<div class="tm-keys">' +
      '<button class="tm-btn" data-btn="1" type="button">ЛКМ</button>' +
      '<button class="tm-btn" data-btn="4" type="button">ПКМ</button>' +
      '<button class="tm-key" data-send="\\t" type="button">Tab</button>' +
      '<button class="tm-key" data-send="\\r" type="button">⏎</button>' +
      '</div>' +
      '<div class="tm-wheel">' +
      '<button class="tm-arr" data-dir="up" type="button">▲</button>' +
      '<div class="tm-mid">' +
      '<button class="tm-arr" data-dir="left" type="button">◀</button>' +
      '<button class="tm-arr" data-dir="right" type="button">▶</button>' +
      '</div>' +
      '<button class="tm-arr" data-dir="down" type="button">▼</button>' +
      '</div>' +
      '<button class="tm-close" type="button" title="Скрыть мышь">✕</button>';

    var mark = document.createElement('div');
    mark.className = 'tm-mark';

    st.bar = bar;
