/* =========================================================================
 * term-mouse.css — полоса виртуальной мыши терминала (СЕНСОР/ЛКМ/ПКМ/колесо).
 *
 * Общая для панели, десктопа и /term: раньше у каждой страницы была своя
 * копия .term-scroll, и в term-app.js она вела себя иначе. Разметку и логику
 * держит term-mouse.js, здесь только вид — такой же, как полоса «мыши» на
 * вкладке «Экран» (lm-* в mobile.html), только ниже и без перекрытия угла.
 * ========================================================================= */

.tmouse {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 99990;
  display: flex; gap: 6px; align-items: stretch;
  padding: 6px 26px 6px 6px;
  padding-bottom: calc(6px + env(safe-area-inset-bottom));
  background: linear-gradient(180deg, rgba(13, 17, 23, .74), rgba(13, 17, 23, .95));
  border-top: 1px solid rgba(240, 246, 252, .18);
  backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
  touch-action: none;
  -webkit-user-select: none; user-select: none; -webkit-touch-callout: none;
}
.tmouse[hidden] { display: none; }

/* СЕНСОР — колесо мыши; с зажатой ЛКМ/ПКМ та же тяга ведёт курсор. */
.tm-pad {
  flex: 1 1 auto; min-width: 84px; min-height: 54px;
  border-radius: 10px; border: 1px dashed rgba(240, 246, 252, .28);
  background: rgba(255, 255, 255, .05);
  display: flex; align-items: center; justify-content: center;
  color: var(--t3, #8b949e); font-size: 10px; line-height: 1.3; text-align: center;
  padding: 0 8px; touch-action: none; position: relative; overflow: hidden;
}
.tm-pad.active { background: rgba(88, 166, 255, .16); border-color: var(--acc, #58a6ff); }
.tm-pad.aim { background: rgba(88, 166, 255, .22); border-style: solid; border-color: var(--acc, #58a6ff); }
.tm-hint { pointer-events: none; }
.tm-hint.warn { color: var(--warn, #d29922); }

/* Кнопки мыши и два клавиши, которые в терминале нужны постоянно. */
.tm-keys { display: flex; flex-direction: column; gap: 4px; width: 86px; flex: 0 0 auto; }
.tm-btn, .tm-key {
  flex: 1 1 0; min-height: 0; padding: 0; border-radius: 8px;
  border: 1px solid rgba(240, 246, 252, .22); background: rgba(255, 255, 255, .07);
  color: #e6edf3; font-size: 11px; font-weight: 700; font-family: inherit;
  touch-action: none; -webkit-user-select: none; user-select: none;
  -webkit-touch-callout: none; -webkit-tap-highlight-color: transparent;
}
.tm-key { font-size: 10px; font-weight: 600; opacity: .82; }
.tm-btn.on, .tm-btn:active { background: var(--acc, #58a6ff); color: #0d1117; border-color: var(--acc, #58a6ff); }
.tm-key.on, .tm-key:active { background: var(--bdr, #30363d); opacity: 1; }
.tm-btn.dim { opacity: .38; }

/* Колесо: ▲▼ по вертикали, ◀▶ по горизонтали. */
.tm-wheel { display: flex; flex-direction: column; gap: 3px; width: 78px; align-items: center; justify-content: center; flex: 0 0 auto; }
.tm-mid { display: flex; gap: 3px; }
.tm-arr {
  width: 36px; height: 24px; padding: 0; border-radius: 7px;
  border: 1px solid rgba(240, 246, 252, .22); background: rgba(255, 255, 255, .07);
  color: #e6edf3; font-size: 12px; line-height: 1; font-family: inherit;
  touch-action: none; -webkit-tap-highlight-color: transparent;
}
.tm-arr.on, .tm-arr:active { background: var(--acc, #58a6ff); color: #0d1117; border-color: var(--acc, #58a6ff); }
.tm-arr.dim { opacity: .35; }

.tm-close {
  position: absolute; top: 50%; right: 3px; transform: translateY(-50%);
  width: 22px; height: 22px; padding: 0; border-radius: 50%;
  border: 1px solid rgba(240, 246, 252, .25); background: rgba(13, 17, 23, .8);
  color: #e6edf3; font-size: 10px; line-height: 1;
}

/* Виртуальный курсор поверх экрана: показывает клетку, куда придётся клик. */
.tm-mark {
  position: absolute; display: none; z-index: 3; pointer-events: none;
  border: 1px solid var(--acc, #58a6ff); border-radius: 2px; opacity: .45;
  box-shadow: 0 0 0 1px rgba(13, 17, 23, .55), 0 0 8px rgba(88, 166, 255, .3);
  transition: opacity .12s ease;
}
.tm-mark.on { opacity: 1; border-color: #fff; }

@media (max-width: 400px) {
  .tm-keys { width: 76px; }
  .tm-wheel { width: 72px; }
  .tm-arr { width: 33px; height: 22px; }
}

