      clientX: Math.round(p.x), clientY: Math.round(p.y),
      button: button || 0, buttons: buttons || 0
    }));
    return true;
  } catch (e) { return false; }
}

// ── состояние панели ─────────────────────────────────────────────────────
function setAimFrom(st, clientX, clientY) {
  var m = metrics(st);
  if (!m) return;
  st.aim = {
    col: clamp(Math.floor((clientX - m.left) / m.cw), 0, st.term.cols - 1),
    row: clamp(Math.floor((clientY - m.top) / m.ch), 0, st.term.rows - 1)
  };
